from module_adapters._graph_extended_support import Diagram,validate
SOURCE='ggnn-modules/model.py';KEY='ggnn_step'
LINKS=[('state','incoming.linear','in','tensor'),('state','outgoing.linear','in','tensor'),('adj','split','in','topology'),('incoming.pack','ain','states','tensor'),('outgoing.pack','aout','states','tensor'),('split','ain','A_in','topology'),('split','aout','A_out','topology'),('ain','cat','a_in','tensor'),('aout','cat','a_out','tensor'),('state','cat','current','retained_value'),('cat','reset.linear','in','tensor'),('cat','update.linear','in','tensor'),('reset.sigmoid','reset_state','r','tensor'),('state','reset_state','state','retained_value'),('ain','joined','a_in','retained_value'),('aout','joined','a_out','retained_value'),('reset_state','joined','reset_state','tensor'),('joined','candidate.linear','in','tensor'),('update.sigmoid','blend','z','retained_value'),('state','blend','state','retained_value'),('candidate.tanh','blend','candidate','tensor'),('blend','output','in','tensor'),('blend','state','next_iteration','loop_recurrence')]
REQUIRED={'incoming.linear':dict(parameter_families=['in_0','in_1'],shared_across_iterations=True),'outgoing.linear':dict(parameter_families=['out_0','out_1'],shared_across_iterations=True),'cat':dict(order=['a_in','a_out','state_cur'],dim=2),'joined':dict(order=['a_in','a_out','r*state_cur'],dim=2),'blend':dict(expression='(1 - z) * state_cur + z * h_hat'),'candidate.linear':dict(parameter='propogator.tansform.0')}
CONTRACTS=[('GGNN.forward','self.in_fcs[i](prop_state)'),('GGNN.forward','self.out_fcs[i](prop_state)'),('GGNN.forward','range(self.n_steps)'),('Propogator.forward','torch.bmm(A_in, state_in)'),('Propogator.forward','torch.bmm(A_out, state_out)'),('Propogator.forward','torch.cat((a_in, a_out, state_cur), 2)'),('Propogator.forward','torch.cat((a_in, a_out, r * state_cur), 2)'),('Propogator.forward','(1 - z) * state_cur + z * h_hat')]
def build():
 d=Diagram(KEY,'GGNN typed-edge propagation step',SOURCE,'GGNN.forward','One repeatable GGNN propagation step + Propogator update; excludes annotations and self.out task readout.',dict(n_node=4,state_dim=8,n_edge_types=2,n_steps=3,iteration_template=True,gates='reset/update; GRU-style interpolation',readout_excluded=True))
 init=d.ref('GGNN.__init__');pi=d.ref('Propogator.__init__');pf=d.ref('Propogator.forward');d.ref('AttrProxy.__getitem__')
 d.input('state','Current node state H_t','[B,4,8]');d.input('adj','Directed typed adjacency A','[B,4,16]',kind='control')
 for branch,parameter in [('incoming','in'),('outgoing','out')]:
  d.stage(branch,branch.title()+' type maps','[B,8,8]',0,[('linear','Two distinct Linear 8 -> 8','linear','2 x [B,4,8]',dict(parameter_families=[parameter+'_0',parameter+'_1'],shared_across_iterations=True)),('pack','Stack / transpose / view T*N','tensor','[B,8,8]',dict(type_major_order=True))],source=[init,d.entry])
 d.node('split','Slice incoming / outgoing blocks','tensor','2 x [B,4,8]',0,source=pf,split_width='N*T=8')
 for name,side in [('ain','in'),('aout','out')]:d.node(name,'BMM A_'+side+' @ states','bmm','[B,4,8]',1,source=pf,expression='torch.bmm(A_'+side+', state_'+side+')')
 d.node('cat','Concat messages + current state','cat','[B,4,24]',2,source=pf,**REQUIRED['cat'])
 for branch in ['reset','update']:
  d.stage(branch,branch.title()+' gate','[B,4,8]',3,[('linear','Linear 24 -> 8','linear','[B,4,8]',dict(parameter='propogator.'+branch+'_gate.0')),('sigmoid','Sigmoid','sigmoid','[B,4,8]',dict())],source=[pi,pf])
 d.node('reset_state','r * SAME current state','multiply','[B,4,8]',4,source=pf)
 d.node('joined','Concat messages + reset state','cat','[B,4,24]',5,source=pf,**REQUIRED['joined'])
 d.stage('candidate','Candidate transform / source tansform','[B,4,8]',6,[('linear','Linear 24 -> 8','linear','[B,4,8]',REQUIRED['candidate.linear']),('tanh','Tanh candidate','tanh','[B,4,8]',dict())],source=[pi,pf])
 d.node('blend','GRU-style complementary blend','add','[B,4,8]',7,source=pf,**REQUIRED['blend'])
 for s,t,p,r in LINKS:d.edge(s,t,p,r,ss='left' if r in ('retained_value','loop_recurrence') else 'out',ds='left' if r=='loop_recurrence' else 'in',sp=p if s=='split' else 'out')
 return d.build(pf,'[B,4,8]','GGNNStep.md',['Two edge types own distinct in_i and out_i Linear modules; all time steps reuse these same four modules and the same Propogator gates.','Adjacency packs incoming and outgoing typed blocks. Separate BMMs form messages; source concatenates both messages and current state for two gates.','Reset r acts on current state before candidate formation. Update formula is (1-z)*state_cur+z*h_hat, preserving the source gate convention.','Class is misspelled Propogator and candidate member tansform in source; identities preserve those spellings.'],['Do not replace actual gates with opaque nn.GRU or LSTM merely because the docstring says LSTM.','Do not share in_i and out_i or give each time step fresh learned parameters.'])
SOURCE_PORTS=[('split','ain','A_in','A_in'),('split','aout','A_out','A_out')]
def validate_ir(ir):return validate(ir,KEY,REQUIRED,LINKS,dict(n_edge_types=2,n_steps=3,readout_excluded=True),SOURCE_PORTS)
